using System.IO;using System.Text.Json;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using System.Windows.Media.Imaging;using RAWSelectionAssistant.Core.Services.Projects;using RAWSelectionAssistant.Services;using RAWSelectionAssistant.ViewModels;using RAWSelectionAssistant.Views;using static RAWSelectionAssistant.WpfTests.RuntimeCorrectionWpfTests;
namespace RAWSelectionAssistant.WpfTests;
[TestClass][DoNotParallelize]public class R55ViewingTests
{
 static string Root(){var root=Environment.GetEnvironmentVariable("KITAO_R55_ROOT")??Path.Combine(Path.GetTempPath(),"r55-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);return root;}
 static string Image(string root){Directory.CreateDirectory(root);var path=Path.Combine(root,"r55-test-input.png");var data=new byte[240*160*3];for(int y=0;y<160;y++)for(int x=0;x<240;x++){var i=(y*240+x)*3;data[i]=(byte)x;data[i+1]=(byte)y;data[i+2]=(byte)(40+(x+y)%180);}var b=BitmapSource.Create(240,160,96,96,PixelFormats.Rgb24,null,data,720);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(b));using var f=File.Create(path);png.Save(f);return path;}
 static void Layout(FrameworkElement view,int width=1366){view.Measure(new Size(width,width==1366?768:1080));view.Arrange(new Rect(0,0,width,width==1366?768:1080));view.UpdateLayout();}
 static void Capture(FrameworkElement view,string path){view.UpdateLayout();var image=new RenderTargetBitmap((int)view.ActualWidth,(int)view.ActualHeight,96,96,PixelFormats.Pbgra32);image.Render(view);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(image));using var f=File.Create(path);png.Save(f);}
 [TestMethod]public Task CentralHostRestoresFilmstripAndOriginalTarget()=>RunSta(async()=>{EnsureTestApplication();var root=Root();using var vm=new ReferenceColorWorkspaceViewModel(new CompanyViewingMeasurementsTests.Dialogs());await vm.LoadTargetAsync(Image(root));await vm.CreateR53VariantAsync(true);vm.ActiveTarget!.IsSelected=true;vm.PinSelectedViewingVariants();var page=new PhotoGradePageView{DataContext=vm};Layout(page);var strip=(Border)page.FindName("FilmstripArea");var original=strip.Parent;var target=vm.ActiveTarget;var count=Application.Current.Windows.Count;await page.ToggleViewingTableAsync();Layout(page);Assert.IsTrue(page.ViewingMode);Assert.AreNotSame(original,strip.Parent);Assert.AreEqual(count,Application.Current.Windows.Count);foreach(var width in new[]{1366,1920}){Layout(page,width);Capture(page,Path.Combine(root,$"OFFSCREEN-r55-central-{width}.png"));}await page.ToggleViewingTableAsync();Layout(page);Assert.IsFalse(page.ViewingMode);Assert.AreSame(original,strip.Parent);Assert.AreSame(target,vm.ActiveTarget);page.DataContext=null;});
 [TestMethod]public Task CancelKeepsCompletedFrameAndGestureUndoRestoresLayout()=>RunSta(async()=>{EnsureTestApplication();var root=Path.Combine(Root(),"cancel");using var vm=new ReferenceColorWorkspaceViewModel(new CompanyViewingMeasurementsTests.Dialogs());await vm.LoadTargetAsync(Image(root));await vm.CreateR53VariantAsync(true);vm.ActiveTarget!.IsSelected=true;vm.PinSelectedViewingVariants();var first=vm.ViewingTable.Items.Single();await vm.CreateR53VariantAsync(false);vm.PinSelectedViewingVariants();var blocker=new TaskCompletionSource<BitmapSource>(TaskCreationOptions.RunContinuationsAsynchronously);var started=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var existing=vm.Editor.SourceImage!;int calls=0;vm.ViewingRenderOverride=(i,e,t)=>++calls==1?Task.FromResult(existing):Wait();Task<BitmapSource> Wait(){started.TrySetResult();return blocker.Task;}var work=vm.PrepareViewingTableAsync();await started.Task;Assert.AreEqual(1,vm.ViewingFrames.Count);vm.CancelViewing();blocker.SetResult(existing);await work;Assert.AreEqual(1,vm.ViewingFrames.Count);var state=JsonSerializer.Serialize(vm.ViewingTable);vm.BeginViewingGesture();vm.SetViewingPlacement(first.TargetId,first.VariantId,500,400,1.5,45);vm.SetViewingPlacement(first.TargetId,first.VariantId,530,430,1.6,48);vm.CommitViewingGesture();vm.UndoViewing();Assert.AreEqual(state,JsonSerializer.Serialize(vm.ViewingTable));vm.RedoViewing();Assert.AreEqual(48,vm.ViewingTable.Items.First(i=>i.VariantId==first.VariantId).Rotation);vm.ClearViewingPlacements();Assert.AreEqual(0,vm.ViewingTable.Items.Count);vm.UndoViewing();Assert.AreEqual(2,vm.ViewingTable.Items.Count);});
 [TestMethod]public Task FullHundredFilmSavesNewVariantWithoutDroppingPinnedItems()=>RunSta(async()=>{EnsureTestApplication();var root=Path.Combine(Root(),"capacity");using var vm=new ReferenceColorWorkspaceViewModel(new CompanyViewingMeasurementsTests.Dialogs());await vm.LoadTargetAsync(Image(root));await vm.CreateR53VariantAsync(true);vm.ActiveTarget!.IsSelected=true;vm.PinSelectedViewingVariants();var source=vm.ViewingTable.Items.Single();var target=vm.ActiveTarget;var items=new List<ViewingTableItem>{source};for(int i=1;i<100;i++){var id=Guid.NewGuid();var version=source.FrozenVariant with{Id=id,Name="fixed"+i};items.Add(source with{VariantId=id,FrozenVariant=version,RecipeHash=FilmBackendBindingV1.HashRecipe(version),Z=i});}vm.Layout=vm.Layout with{ViewingTable=new ViewingTableState(2,items)};var ids=items.Select(i=>i.VariantId).ToArray();var before=target.EditVersions.Count;Assert.IsNull(await vm.ViewingFilmAvailabilityAsync(source));var result=await vm.GenerateViewingFilmAsync(source);Assert.IsNotNull(result);Assert.AreEqual(before+1,target.EditVersions.Count);CollectionAssert.AreEqual(ids,vm.ViewingTable.Items.Select(i=>i.VariantId).ToArray());StringAssert.Contains(vm.FilmTaskStatus,"已满");});
 [TestMethod]public Task LayoutViewportOrderPreferencesAndProjectReopen()=>RunSta(async()=>{EnsureTestApplication();var root=Path.Combine(Root(),"reopen");using var vm=new ReferenceColorWorkspaceViewModel(new CompanyViewingMeasurementsTests.Dialogs());await vm.LoadTargetAsync(Image(root));await vm.CreateR53VariantAsync(true);vm.ActiveTarget!.IsSelected=true;vm.PinSelectedViewingVariants();var item=vm.ViewingTable.Items.Single();vm.SetViewingViewport(.7,120,88);vm.SetViewingPlacement(item.TargetId,item.VariantId,340,210,1.4,37);vm.SetViewingLight(true);vm.SetViewingBrightness(1.2);var file=Path.Combine(root,"r55-"+Guid.NewGuid().ToString("N")+".ptstudio.json");await vm.SaveSessionAsync(file);var expected=JsonSerializer.Serialize(vm.ViewingTable);using var other=new ReferenceColorWorkspaceViewModel(new CompanyViewingMeasurementsTests.Dialogs());await other.LoadSessionAsync(file);Assert.AreEqual(expected,JsonSerializer.Serialize(other.ViewingTable));await File.WriteAllTextAsync(Path.Combine(Root(),"R55_EXPECTED.json"),JsonSerializer.Serialize(new{pid=Environment.ProcessId,file,expected}));var preferences=new ViewingPreferences(true,true,false,true);preferences.Save();Assert.AreEqual(preferences,ViewingPreferences.Load());Assert.IsFalse(JsonSerializer.Serialize(vm.Layout).Contains("LeftOpen"));new ViewingPreferences().Save();});
 [TestMethod]public Task SidebarsPreflightLampNeverMutateRecipeAndClosePanelKeepsTask()=>RunSta(async()=>{EnsureTestApplication();new ViewingPreferences().Save();var root=Path.Combine(Root(),"sidebar");using var vm=new ReferenceColorWorkspaceViewModel(new CompanyViewingMeasurementsTests.Dialogs());await vm.LoadTargetAsync(Image(root));await vm.CreateR53VariantAsync(true);vm.ActiveTarget!.IsSelected=true;vm.PinSelectedViewingVariants();await vm.PrepareViewingTableAsync();var view=new StudioViewingTableView(vm);Layout(view);Assert.AreEqual(22,view.LeftSidebarWidth);Assert.AreEqual(22,view.RightSidebarWidth);view.SelectForTest(vm.ViewingFrames.Single());Assert.AreEqual(22,view.RightSidebarWidth);var recipe=JsonSerializer.Serialize(vm.ViewingTable.Items.Single().FrozenVariant);var pixels=Hash(vm.ViewingFrames.Single().Image);view.ToggleLampForTest();Assert.AreEqual(recipe,JsonSerializer.Serialize(vm.ViewingTable.Items.Single().FrozenVariant));Assert.AreEqual(pixels,Hash(vm.ViewingFrames.Single().Image));view.OpenFilmSidebarForTest();await view.PreflightForTest();Assert.IsTrue(view.GenerateEnabled);Assert.AreEqual(280,view.RightSidebarWidth);view.CloseSidebarForTest();Assert.AreEqual(22,view.RightSidebarWidth);Assert.AreEqual(recipe,JsonSerializer.Serialize(vm.ViewingTable.Items.Single().FrozenVariant));view.Close();new ViewingPreferences().Save();});
 static string Hash(BitmapSource source){var f=new FormatConvertedBitmap(source,PixelFormats.Bgra32,null,0);var data=new byte[f.PixelWidth*f.PixelHeight*4];f.CopyPixels(data,f.PixelWidth*4,0);return Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(data));}

 [TestMethod]public Task IndependentR55LayoutReopen()=>RunSta(async()=>{EnsureTestApplication();var path=Path.Combine(Root(),"R55_EXPECTED.json");if(!File.Exists(path)){Assert.Inconclusive("Prior independent fixture required");return;}using var expected=JsonDocument.Parse(await File.ReadAllTextAsync(path));Assert.AreNotEqual(Environment.ProcessId,expected.RootElement.GetProperty("pid").GetInt32());using var vm=new ReferenceColorWorkspaceViewModel(new CompanyViewingMeasurementsTests.Dialogs());await vm.LoadSessionAsync(expected.RootElement.GetProperty("file").GetString()!);Assert.AreEqual(expected.RootElement.GetProperty("expected").GetString(),JsonSerializer.Serialize(vm.ViewingTable));});
}
